                    discounts: [Stripe.Shared.Discounts]? = nil,
                    taxes: [Stripe.Shared.Taxes]? = nil
                ) {
                    self.discounts = discounts
                    self.taxes = taxes
                }
            }
        }

        public struct WalletOptions: Codable, Hashable, Sendable {
            public var link: Link?

            private enum CodingKeys: String, CodingKey {
                case link
            }

            public init(
                link: Link? = nil
            ) {
                self.link = link
            }

            public struct Link: Codable, Hashable, Sendable {
                /// Describes whether Checkout should display Link.
                public var display: Display?

                private enum CodingKeys: String, CodingKey {
                    case display
                }

                public init(
                    display: Display? = nil
                ) {
                    self.display = display
                }

                /// Describes whether Checkout should display Link.
                public enum Display: String, Codable, Hashable, Sendable {
                    case auto
                    case never
                }
            }
        }
    }
}
